#!/bin/bash
cd "$(dirname "$0")/../.."
node scripts/portraits/select-source.js --slug michael-jordan --url 'https://cdn.nba.com/manage/2021/07/GettyImages-2912666.jpg' --page 'https://www.nba.com/news/history-season-review-1996-97' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'May 1997 (1997 Eastern Conference Finals vs MIA, United Center)' --crop 125,164,450 --scores 2,1,3,2,2,2,1 --energy 7 --vs-mccain 'matches (looking off-camera, mouth open mid-breath during a break in play)' --jersey 'CHI white home 1996-97 (1997 ECF)' --concerns 'face ~170px (crop 450px, will be upscaled); film grain, slightly soft; Pippen and Rodman in the full frame but outside the crop' --alt 'https://cdn.nba.com/manage/2025/03/GettyImages-973250614-scaled.jpg (May 23 1998 at IND, sharp 373px face, but a locked-in stare at the camera, energy ~6)' --alt 'https://cdn.nba.com/manage/2026/10/GettyImages-973245804.jpg (May 25 1998 at IND, 414px, side-eye glare with mouth closed and tape on brow, energy ~5.5)'
node scripts/portraits/select-source.js --slug kobe-bryant --url 'https://upload.wikimedia.org/wikipedia/commons/4/4e/Kobe_Bryant_7144_adjusted.jpg' --page 'https://commons.wikimedia.org/wiki/File:Kobe_Bryant_7144_adjusted.jpg' --license 'Public domain' --author 'Sgt. Joseph A. Lee' --date 'October 2005 (preseason game vs GSW, Honolulu)' --crop 497,168,1200 --scores 3,3,3,2,2,2,1 --energy 7 --vs-mccain 'matches (at the free-throw line looking up at the rim, mouth open mid-breath)' --jersey 'LAL gold home #8, 2005-06 preseason' --concerns 'FLAG: preseason game (Oct 2005 vs GSW, Honolulu), not regular season, though a real game in the regular gold home uniform; head tilted up. Regular-season fallback is the Lipofsky alt' --alt 'https://upload.wikimedia.org/wikipedia/commons/0/0b/Lipofsky_Kobe_%28high_quality%29.jpg (CC BY-SA 3.0 Lipofsky, Dec 20 1999 regular season, purple #8, mouth open, energy 7, but arms raised mid-free-throw frame the head in the crop)' --alt 'https://cdn.nba.com/manage/2025/04/GettyImages-139369178-scaled-e1744829768258.jpg (Feb 19 2012 at PHX, purple, lips pursed looking off, energy 6, hands tugging jersey in crop)'
node scripts/portraits/select-source.js --slug shaquille-o-neal --url 'https://cdn.nba.com/manage/2025/06/GettyImages-610811so.jpg' --page 'https://www.nba.com/news/nba-birthdays-players-born-on-march-6' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2001-02 season (at PHX, America West Arena; 9/11 ribbon patch)' --crop 381,0,792 --scores 3,3,2,2,2,2,1 --energy 5 --vs-mccain 'lower (catching his breath between plays, sweat streaming, lips pushed out, eyes up and ahead)' --jersey 'LAL purple road #34, 2001-02' --concerns 'FLAG: energy 5 (no in-game Lakers photo of Shaq in the 6-8 band found on nba.com or Commons after widening, Archive 75 and season-review pages, and the Lakers legacy gallery, which is watermarked); Getty caption (id 610811) confirms in-game vs PHX; hands on hips at frame edges, outside crop' --alt 'https://cdn.nba.com/manage/2018/07/Shaq_Miami_ISO.jpg (renamed nba.com, MIA black 2007-08, sweaty in-game grin looking off, energy ~6, but Heat and past his prime)' --alt 'https://cdn.nba.com/manage/2021/08/kobe-shaq-top-moments-game-7-2000.jpg (LAL gold 2000 WCF, lips parted, energy ~5, Kobe under his arm, head touches the top edge)'
node scripts/portraits/select-source.js --slug tim-duncan --url 'https://cdn.nba.com/manage/2019/07/tim-duncan-iso-archive.jpg' --page 'https://www.nba.com/news/spurs-hire-tim-duncan-assistant-coach-release' --license 'unknown (NBA.com)' --author 'NBA.com' --date 'c. 1998-2001 (old Spurs black road uniform, undated archive photo)' --crop 408,0,1080 --scores 3,3,3,1,2,2,1 --energy 6.5 --vs-mccain 'matches (at the free-throw line, eyes up at the rim, lips parted)' --jersey 'SAS black road (pre-2002 design), c. 1998-2001' --concerns 'renamed nba.com image, no Getty caption check, but clearly young Duncan; the ball fills the lower half of the crop and hides the SPURS wordmark (only trim and NBA logo visible); exact date unverified' --alt 'https://cdn.nba.com/manage/2025/02/GettyImages-106640541-scaled-e1740596827970.jpg (Feb 2010 vs CHA, black road, mouth open watching his shot, energy 7, but face 214px, near-profile, arm raised across left of crop)' --alt 'https://cdn.nba.com/manage/2018/04/Duncan_ISO_1998.jpg (1998 rookie, black road, 382px, but a neutral stare, energy ~4)'
node scripts/portraits/select-source.js --slug kevin-garnett --url 'https://cdn.nba.com/manage/2025/12/GettyImages-52946289-scaled-e1766093546251.jpg' --page 'https://www.nba.com/news/celtics-will-retire-kevin-garnett-number-official-release' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2005-04-20 (vs SAS, Target Center)' --crop 740,0,1000 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches in intensity, different mood (confident closed-mouth grin, fist to chest, eyes up and ahead)' --jersey 'MIN white home 2004-05' --concerns 'mild in-game celebration (fist to chest), mouth closed; fist enters lower right of crop' --alt 'https://cdn.nba.com/manage/2021/05/kevin-garnett-1997.jpg (renamed nba.com, young KG laughing, MIN blue collar only, 633px, energy ~7.5, but no caption and context unclear)' --alt 'https://upload.wikimedia.org/wikipedia/commons/8/88/Kevin_Garnett_2008.jpg (CC BY-SA 2.0, BOS green road 2008, fingers to temple mouth open, energy ~7, but Celtics not MIN)'
node scripts/portraits/select-source.js --slug dirk-nowitzki --url 'https://cdn.nba.com/manage/2021/11/GettyImages-114489419-scaled-e1637272247843.jpg' --page 'https://www.nba.com/news/mavericks-playoff-spot-clinch-dirk' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2011-05-21 (2011 WCF Game 3 at OKC)' --crop 719,0,1021 --scores 3,3,3,2,2,2,1 --energy 7 --vs-mccain 'matches (reacting after a play, mouth open, looking off-camera)' --jersey 'DAL blue alternate 2010-11 (2011 WCF)' --concerns 'mouth open showing upper teeth, a touch more reactive than McCain; wet hair' --alt 'https://cdn.nba.com/manage/2023/02/GettyImages-115272156.jpg (2011 Finals G3 vs MIA, white home, mouth open looking off, energy 7, but 297px, softer, nearer profile, Wade in frame)' --alt 'https://upload.wikimedia.org/wikipedia/commons/1/1d/Dirk_Nowitzki_2_%28cropped%29.jpg (CC BY-SA 2.0 Keith Allison, navy road 2008, 754px, but looking down, energy ~5)'
node scripts/portraits/select-source.js --slug allen-iverson --url 'https://cdn.nba.com/manage/2024/03/GettyImages-71063313.jpg' --page 'https://www.nba.com/news/philadelphia-76ers-unveil-allen-iverson-sculpture' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2001-06-06 (2001 NBA Finals Game 1 at LAL)' --crop 490,0,946 --scores 3,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (standing at halfcourt, looking off-camera, lips parted)' --jersey 'PHI black alternate 2000-01 with NBA Finals patch' --concerns 'a little calmer than McCain; hands on hips just outside crop' --alt 'https://cdn.nba.com/manage/2025/09/GettyImages-96870786.jpg (Jan 13 2010 vs NYK, PHI white, pointing with mouth open, energy 7, but red-sleeved arm fills a third of the crop and 2009-10 is his late return)' --alt 'https://cdn.nba.com/manage/2025/06/GettyImages-1246553475ai.jpg (Nov 11 2003 at WAS, PHI black, mouth open, energy 6.5, but 224px and softer)'
node scripts/portraits/select-source.js --slug steve-nash --url 'https://cdn.nba.com/manage/2023/09/steve-nash-dribbles-iso.jpg' --page 'https://www.nba.com/news/steve-nash-joins-suns-senior-adviser' --license 'unknown (NBA.com)' --author 'NBA.com' --date 'c. 2005-2010 (PHX white home, undated)' --crop 510,8,847 --scores 3,3,2,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (bringing the ball up, eyes off-camera, tongue out between his lips)' --jersey 'PHX white home, c. 2005-10' --concerns 'tongue out (his habit) may read oddly in a portrait; renamed nba.com image, no Getty caption check, but clearly Nash; date unverified; ball at right edge of crop' --alt 'https://cdn.nba.com/manage/2022/03/GettyImages-56373984-scaled.jpg (Dec 7 2005 at GSW, purple road, calling a play with mouth open, energy 7, but heavily upscaled and blocky)' --alt 'https://upload.wikimedia.org/wikipedia/commons/b/b5/Steve_Nash.jpg (CC BY-SA 2.0, purple road 2009, 551px, but mouth agape mid-drive, energy ~8.5)'
node scripts/portraits/select-source.js --slug dwyane-wade --url 'https://upload.wikimedia.org/wikipedia/commons/b/bc/Dwyane_Wade.jpg' --page 'https://commons.wikimedia.org/wiki/File:Dwyane_Wade.jpg' --license 'CC BY-SA 2.0' --author 'Keith Allison from Baltimore, USA' --date '2009-04-04 (Heat at Wizards, Verizon Center)' --crop 165,80,1094 --scores 3,3,3,2,2,2,1 --energy 6.5 --vs-mccain 'matches (dribbling upcourt, looking off-camera, lips parted)' --jersey 'MIA red road 2008-09' --concerns 'slight noise from high-ISO arena shot; ball at lower right edge of the full frame, outside crop' --alt 'https://cdn.nba.com/manage/2022/12/GettyImages-146491665-scaled-e1671655854897.jpg (2012 Finals G3 vs OKC, white with Finals patch, fist clenched looking off, energy ~5.5, mouth closed, 248px, softer)' --alt 'https://upload.wikimedia.org/wikipedia/commons/7/73/Dwyane_Wade_e1.jpg (CC BY-SA 2.0, Mar 30 2011 at WAS, black road, 353px, but a neutral stare, energy ~4)'
node scripts/portraits/select-source.js --slug jason-kidd --url 'https://cdn.nba.com/manage/2025/06/GettyImages-72750655jk.jpg' --page 'https://www.nba.com/news/brooklyn-nets-single-season-assists-per-game-leaders' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '2006-11-10 (vs MIA, Continental Airlines Arena)' --crop 592,0,780 --scores 3,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (standing on court, looking up off-camera, brow knit, lips parted)' --jersey 'NJN white home 2006-07' --concerns 'a little calmer than McCain; head close to top edge of crop (no clipping)' --alt 'https://upload.wikimedia.org/wikipedia/commons/2/27/Jason_Kidd_mavs_allison.jpg (CC BY-SA 2.0 Keith Allison, DAL navy road c. 2009, mouth open looking off, energy 7, 479px, but Mavericks not NJN)' --alt 'https://cdn.nba.com/manage/2019/10/131017181228-jason-kidd-nets-player-iso.1280x720.jpg (renamed nba.com, NJN navy road with Finals patch 2002/03, dribbling, energy ~5.5, only 184px in a 1280px frame)'
